self.view.AddProduct.left = "100%";
    self.view.AddProduct.isVisible = true;

    self.view.AddProduct.animate(
        kony.ui.createAnimation({
            "100": {
                "left": "55%",
                "stepConfig": { "timingFunction": kony.anim.EASE_IN_OUT }
            }
        }),
        {
            "delay": 0,
            "duration": 0.3,
            "iterationCount": 1,
            "fillMode": kony.anim.FILL_MODE_FORWARDS
        },
        {
            "animationEnd": function() {
                setTimeout(function() {
                    self.view.AddProduct.animate(
                        kony.ui.createAnimation({
                            "100": {
                                "left": "100%",
                                "stepConfig": { "timingFunction": kony.anim.EASE_IN_OUT }
                            }
                        }),
                        {
                            "delay": 0,
                            "duration": 0.3,
                            "iterationCount": 1,
                            "fillMode": kony.anim.FILL_MODE_FORWARDS
                        },
                        {
                            "animationEnd": function() {
                                self.view.AddProduct.isVisible = false;
                            }
                        }
                    );
                }, 2500);
            }
        }
    );
